int main() {
  std::vector<int> original{3, 1, 3, 0};
  auto sorted = original;
  std::sort(sorted.begin(), sorted.end());
  assert((sorted == std::vector<int>{0, 1, 3, 3}));
  assert(original[0] == 3);

// Reference extension checks for the exercise changes.
auto unique_values = sorted;
unique_values.erase(std::unique(unique_values.begin(), unique_values.end()),
                    unique_values.end());
assert((unique_values == std::vector<int>{0, 1, 3}));

  assert(std::count_if(sorted.begin(), sorted.end(),
                       [](int x) { return x >= 3; }) == 2);
  std::cout << "cpp-007 examples passed\n";
  return 0;
}

struct Batch {
  std::vector<int> values;
  std::string label;
};

int main() {
  Batch a{{1, 2, 3}, "first"};
  Batch copy = a;
  copy.values[0] = 9;
  assert(a.values[0] == 1);

Batch moved = std::move(a);
assert((moved.values == std::vector<int>{1, 2, 3}));
a = Batch{{4}, "reused"};
assert(a.values[0] == 4);

  // Reference extension checks for the exercise changes.
  auto make_batch = []() { return Batch{{8, 9}, "factory"}; };
  auto returned = make_batch();
  assert((returned.values == std::vector<int>{8, 9}));
  std::cout << "cpp-016 examples passed\n";
  return 0;
}

int main() {
  std::mutex m;
  std::condition_variable cv;
  std::queue<int> q;
  bool closed = false;
  int total = 0;

std::thread consumer([&] {
  std::unique_lock<std::mutex> lock(m);
  for (;;) {
    cv.wait(lock, [&] { return !q.empty() || closed; });
    if (q.empty() && closed)
      break;
    total += q.front();
    q.pop();
  }
});

{
  std::lock_guard<std::mutex> lock(m);
  q.push(2);
  q.push(3);
  closed = true;
}
cv.notify_all();
consumer.join();

  assert(total == 5);
  // Reference extension checks for the exercise changes.
  std::queue<int> empty_queue;
  bool empty_closed = true;
  assert(empty_queue.empty() && empty_closed);
  std::cout << "cpp-030 examples passed\n";
  return 0;
}
